state.canonical_source:
# Help the workspace operator recruit receptionists, community managers, sales staff, and facilities technicians for specific locations. @{nl="Help de werkplekbeheerder receptionisten, communitymanagers, verkopers en facilitaire technici voor specifieke locaties te werven."}
app CanHire uses=[hire]

# Recruit employees, prepare onboarding and acknowledge published training versions. @{nl="Werf medewerkers, bereid hun inwerking voor en bevestig gepubliceerde opleidingsversies."}
app PeopleDevelopment uses=[CanHire,CanOnboard,CanLearn]

# Keep vacancy intake, interview feedback and reviewed hiring handoff private. @{nl="Houd vacatureaanmeldingen, gespreksfeedback en de beoordeelde aanstellingsoverdracht privé."}
package hire label="Recruitment"@{nl="Werving"}
 use rent_catalog {Location,test_site}
 use employee {Employee,can_work}
 use std {EmailV1 as Mail} from=deployment.mail
 use shift {ScheduleV1 as StaffSchedule} from=deployment.staff_schedule
 Given
  message heading_own_application_outcomes = "Own application outcomes"@{nl="Eigen sollicitatieresultaten"}
  message label_interviewer = "Interviewer"@{nl="Interviewer"}
  message label_Candidate_application = "Application text"@{nl="Sollicitatietekst"}
  message label_Candidate_cv = "CV attachment"@{nl="CV-bijlage"}
  message label_Candidate_source = "Source reference"@{nl="Bronreferentie"}
  message label_Candidate_stage_interview = "Interview"@{nl="Sollicitatiegesprek"}
  message label_Interview_from = "Start"@{nl="Begin"}
  message label_Interview_until = "End"@{nl="Einde"}
  message label_Interview_feedback = "Interview feedback"@{nl="Gespreksfeedback"}
  preferences { location:Location?, stage:Candidate.stage? }
  role recruiter label="Recruiter"@{nl="Recruiter"}
  role interviewer label=label_interviewer
  Vacancy { location:Location, title:text trim min=1, description:text, employment:text label="Employment type"@{nl="Dienstverband"}, skills:text[] label="Skills"@{nl="Vaardigheden"}, owner:user server=actor label="Owner"@{nl="Eigenaar"}, published:bool=false label="Published"@{nl="Gepubliceerd"}, open:bool=true label="Open"@{nl="Open"}, closed_at:datetime? label="Closed at"@{nl="Gesloten op"} } label="Vacancy"@{nl="Vacature"}
  Candidate in Vacancy { account:user? label="Account"@{nl="Account"}, name:text, email:email, application:text label=label_Candidate_application, cv:file? label=label_Candidate_cv, source:text label=label_Candidate_source, stage:enum(applied,interview,offer,hired,rejected,withdrawn)=applied label={text="Hiring stage"@{nl="Sollicitatiefase"},values={applied="Applied"@{nl="Toegepast"},interview=label_Candidate_stage_interview,offer="Offer"@{nl="Aanbod"},hired="Hired"@{nl="Aangenomen"},rejected="Rejected"@{nl="Afgewezen"},withdrawn="Withdrawn"@{nl="Ingetrokken"}}}, reason:text?, onboarding_reference:text? label="Onboarding reference"@{nl="Inwerkreferentie"} } label="Candidate"@{nl="Kandidaat"}
  Interview in Candidate { interviewer:Employee label=label_interviewer, from:datetime label=label_Interview_from, until:datetime label=label_Interview_until, timezone:timezone, notes:text?, feedback:text? label=label_Interview_feedback, state:enum(pending,confirmed,cancelled)=pending label={text="State"@{nl="Status"},values={pending="Pending"@{nl="In afwachting"},confirmed="Confirmed"@{nl="Bevestigd"},cancelled="Cancelled"@{nl="Geannuleerd"}}}, source:text unique label=label_Candidate_source, delivery:text? label="Delivery reference"@{nl="Verzendingsreferentie"} } label=label_Candidate_stage_interview
  event InterviewReminder { interview:Interview, revision:int }
  policy Vacancy read=public where=row.published and row.open fields=location,title,description,employment,skills
  policy Vacancy read=recruiter and can_work(actor,row.location)
  policy Candidate read=recruiter and can_work(actor,row.parent.location)
  policy Candidate read=authenticated where=row.account==actor fields=name,email,application,cv,stage,reason
  policy Candidate read=interviewer where=any(row.Interview as interview,interview.interviewer.user==actor and interview.state==confirmed) fields=name,application,cv,stage
  policy Interview read=recruiter and can_work(actor,row.parent.parent.location)
  policy Interview read=interviewer where=row.interviewer.user==actor and row.interviewer.active
  unique Candidate fields=email
  require Interview: row.from<row.until
  fixture vacancy=Vacancy {location=test_site,title="Reception",description="Reception role",employment="Full-time"}
  fixture applicant=Candidate {parent=vacancy,account=self,name="Applicant",email="applicant@example.test",application="Application",source="Verified intake"}
 When
  crud Vacancy by=recruiter fields=title,description,employment,skills,published,open create_fields=location,title,description,employment,skills when=can_work(actor,row.location) delete=none
  # Apply once to a published open vacancy using your verified account. @{nl="Solliciteer één keer op een gepubliceerde open vacature met je geverifieerde account."}
  scenario apply(vacancy:Vacancy,name:text,application:text label=label_Candidate_application,cv:file? label=label_Candidate_cv) by=authenticated label="Apply"@{nl="Solliciteren"}
   require actor.email_verified and vacancy.open and vacancy.published and trim(name)!="" and trim(application)!="" and not any(vacancy.Candidate as candidate,candidate.email==actor.email)
   do create Candidate {parent=vacancy,account=actor,name,email=actor.email,application,cv,source="Verified intake"} as candidate
  # Record recruiter-entered intake and its actual source. @{nl="Registreer een door de recruiter ingevoerde kandidaat en de werkelijke bron."}
  scenario intake(vacancy:Vacancy,name:text,email:email,application:text label=label_Candidate_application,cv:file? label=label_Candidate_cv,source:text label=label_Candidate_source) by=recruiter label="Record candidate intake"@{nl="Kandidaat registreren"}
   require can_work(actor,vacancy.location) and vacancy.open and trim(source)!=""
   do create Candidate {parent=vacancy,name,email,application,cv,source} as candidate
  # Request one interviewer reservation rather than relying on a local interview calendar. @{nl="Vraag één interviewerreservering aan in plaats van op een lokale gesprekskalender te vertrouwen."}
  scenario schedule(candidate:Candidate,interviewer:Employee label=label_interviewer,from:datetime label=label_Interview_from,until:datetime label=label_Interview_until,timezone:timezone) by=recruiter label="Schedule interview"@{nl="Gesprek plannen"}
   require can_work(actor,candidate.parent.location) and candidate.stage in [applied,interview] and interviewer.active and from>=now and from<until
   do
    create Interview {parent=candidate,interviewer,from,until,timezone,source=operation.id} as interview
    send StaffSchedule.reserve {value={source=interview.source,employee=interviewer.user,location=candidate.parent.location.id,from,until,skill="interview",kind=interview,revision=interview.version}} as delivery
    set interview {delivery=delivery.id}
  # Save feedback only from the currently assigned active interviewer. @{nl="Bewaar uitsluitend feedback van de momenteel toegewezen actieve interviewer."}
  scenario feedback(interview:Interview,notes:text) by=interviewer label=label_Interview_feedback
   require interview.interviewer.user==actor and interview.interviewer.active and interview.state==confirmed and trim(notes)!=""
   do set interview {feedback=notes}
  # Record a hiring outcome without granting staff privileges. @{nl="Registreer een aanstellingsresultaat zonder personeelsrechten toe te kennen."}
  scenario decide(candidate:Candidate,stage:Candidate.stage,reason:text) by=recruiter label="Record decision"@{nl="Besluit vastleggen"}
   require can_work(actor,candidate.parent.location) and stage in [offer,hired,rejected] and trim(reason)!="" and candidate.stage!=withdrawn
   do set candidate {stage,reason}
  # Withdraw your application and cancel current interview commitments. @{nl="Trek je sollicitatie in en annuleer huidige gespreksreserveringen."}
  scenario withdraw(candidate:Candidate) by=authenticated label="Withdraw"@{nl="Intrekken"}
   require candidate.account==actor and candidate.stage in [applied,interview,offer]
   do
    set candidate {stage=withdrawn}
    for interview in candidate.Interview as item where item.state in [pending,confirmed] limit=100
     set interview {state=cancelled}
     cancel interview.id
     send StaffSchedule.release {source=interview.source,revision=interview.version} as release
   examples candidate=applicant
    as,candidate.stage -> candidate.stage
    members,applied -> withdrawn
    members,hired -> error(rule_failed)
    public,applied -> error(forbidden)
  scenario reservation on=StaffSchedule.reserve.completed
   do
    for interview in Interview as item where item.delivery==event.delivery_id limit=1
     if event.status==succeeded and event.result!=null and event.result.source==interview.source and event.result.state==confirmed and interview.parent.stage!=withdrawn
      set interview {state=confirmed}
      if interview.from>now+1h
       schedule interview.id at=interview.from-1h event=InterviewReminder {interview,revision=interview.version+1}
  scenario remind on=InterviewReminder
   require event.interview.state==confirmed and event.interview.version==event.revision and event.interview.parent.stage!=withdrawn
   do send Mail.send {to=event.interview.parent.email,subject=format("Interview reminder"@{nl="Herinnering sollicitatiegesprek"},locale=null),body=event.interview.parent.parent.title} when=event.interview.state==confirmed as notice
 Then
  # Find published vacancies and submit your own application. @{nl="Vind gepubliceerde vacatures en dien je eigen sollicitatie in."}
  page /careers title="Careers"@{nl="Vacatures"}
   card "Published vacancies"@{nl="Gepubliceerde vacatures"}
    list Vacancy filter=location search=title defaults={location=preferences.location}
     text row.title,row.location,row.description,row.employment,row.skills
     form apply

  # Follow your own submission without private interviewer feedback. @{nl="Volg je eigen sollicitatie zonder private interviewerfeedback."}
  page /careers/mine title="My applications"@{nl="Mijn sollicitaties"}
   require authenticated
   card heading_own_application_outcomes
    table Candidate columns=name,stage,reason filter=stage defaults={stage=preferences.stage}
     details heading_own_application_outcomes display=drawer
      text row.application,row.cv
      action withdraw

  # Coordinate private candidates and restricted interview evidence. @{nl="Coördineer private kandidaten en afgeschermd gespreksbewijs."}
  page /hiring title="Hiring"@{nl="Werving"}
   require recruiter or interviewer
   card "Vacancy authoring"@{nl="Vacatures beheren"}
    form Vacancy.create
    list Vacancy filter=location search=title defaults={location=preferences.location} display=split
     edit
     form intake
     list row.Candidate filter=stage defaults={stage=preferences.stage}
      text row.name,row.application,row.cv,row.stage
      card "Recruiter decision"@{nl="Besluit van de recruiter"}
       require recruiter and can_work(actor,row.parent.location)
       text row.reason
      actions schedule,decide
      list row.Interview order=from
       details "Interview evidence"@{nl="Gespreksbewijs"} display=drawer
        text row.from,row.until,row.timezone,row.state,row.feedback
        form feedback
      history

# Help workspace HR and location managers prepare new employees for reception, sales, community, and facilities duties. @{nl="Help HR en locatiemanagers nieuwe medewerkers voor receptie-, verkoop-, community- en facilitaire taken voor te bereiden."}
app CanOnboard uses=[employee,onboard]

# Own employee work identity and private, versioned onboarding checklists. @{nl="Beheer de werkidentiteit van medewerkers en private, geversioneerde inwerkchecklists."}
package onboard label=page_people_onboarding_title
 use rent_catalog {Location,test_site}
 use employee {Employee,hr,test_worker,deactivate,can_work}
 Given
  export contract WorkItem { reference:text, revision:int, location:text?, title:text, detail:text?, due:datetime?, action:action(complete) } label="Authorized work item"@{nl="Toegestaan werkitem"}
  export contract WorkBatch { items:WorkItem[]! max=500 } label="Authorized work batch"@{nl="Toegestane werkverzameling"}
  message page_people_onboarding_title = "Onboarding"@{nl="Inwerken"}
  preferences { home:Location? label="Home location"@{nl="Standplaats"}, view:enum(all,unfinished,overdue)=all label={text="Step view"@{nl="Stappenweergave"},values={all="All steps"@{nl="Alle stappen"},unfinished="Unfinished steps"@{nl="Onafgeronde stappen"},overdue="Overdue steps"@{nl="Achterstallige stappen"}}} }
  Template { name:text, role:text label="Role"@{nl="Rol"}, location:Location, active:bool=true label="Available template"@{nl="Beschikbare template"}, revision:int=1 } label="Checklist template"@{nl="Checklisttemplate"}
  TemplateStep in Template { title:text trim min=1, offset_days:int=0 label="Offset in days"@{nl="Verschuiving in dagen"}, category:enum(equipment,induction,account,training)=induction label={text="Category"@{nl="Categorie"},values={equipment="Equipment"@{nl="Uitrusting"},induction="Induction"@{nl="Introductie"},account="Account"@{nl="Account"},training="Training"@{nl="Opleiding"}}} } label="Template step"@{nl="Templatestap"}
  Checklist in Employee { template:Template, template_version:int label="Template version"@{nl="Templateversie"}, started:date label="Started on"@{nl="Gestart op"}, generation:text unique label="Generation reference"@{nl="Generatiereferentie"} } label="Onboarding checklist"@{nl="Inwerkchecklist"}
  export Step in Checklist { title:text trim min=1, due:date, assignee:user label="Assignee"@{nl="Toegewezen persoon"}, category:TemplateStep.category, document:file? label="Generate document"@{nl="Document genereren"}, blocked_reason:text? label="Blocking reason"@{nl="Blokkeerreden"}, done:bool=false, completed_by:user? label="Completed by"@{nl="Afgerond door"}, completed_at:datetime? label="Completed at"@{nl="Afgerond op"} } label="Onboarding step"@{nl="Inwerkstap"}
  derive Checklist.completed_steps:int = count(row.Step as s where s.done) label="Completed steps"@{nl="Afgeronde stappen"}
  derive Checklist.total_steps:int = count(row.Step) label="Active steps"@{nl="Actieve stappen"}
  derive Checklist.progress:decimal = count(row.Step as s where s.done)*100/max([1,count(row.Step)]) label="Progress"@{nl="Voortgang"}
  policy Template read=members and can_work(actor,row.location)
  policy TemplateStep read=members and can_work(actor,row.parent.location)
  policy Checklist read=hr or (authenticated and row.parent.user==actor)
  policy Step read=hr or (authenticated and (row.assignee==actor or row.parent.parent.user==actor))
  require Step: not row.done or (row.completed_at!=null and row.completed_by!=null)
  lock Checklist fields=template,template_version,started,generation
  fixture test_template=Template {name="Opening",role="operator",location=test_site}
  fixture test_checklist=Checklist {parent=test_worker,template=test_template,template_version=1,started=date("2026-10-01"),generation="test-onboarding"}
  fixture test_step=Step {parent=test_checklist,title="Induction",due=date("2026-10-03"),assignee=self,category=induction}
 When
  crud Template by=hr fields=name,role,location,active create_fields=name,role,location
  crud TemplateStep by=hr fields=title,offset_days,category delete=remove
  crud Step by=hr fields=title,due,assignee,category,document,blocked_reason
  scenario template_changed on=Template.update
   do set event.after {revision=event.before.revision+1}
  scenario template_step_created on=TemplateStep.create
   do set event.after.parent {revision=event.after.parent.revision+1}
  scenario template_step_changed on=TemplateStep.update
   do set event.after.parent {revision=event.after.parent.revision+1}
  scenario template_step_removed on=TemplateStep.delete
   do set event.before.parent {revision=event.before.parent.revision+1}
  # Copy a current role/location template once without changing existing checklists. @{nl="Kopieer een huidige rol- en locatietemplate één keer zonder bestaande checklists te wijzigen."}
  scenario start(employee:Employee,template:Template) by=hr label="Start"@{nl="Starten"}
   require employee.active and template.active and employee.role==template.role and employee.home==template.location
   do
    create Checklist {parent=employee,template,template_version=template.revision,started=employee.start,generation=operation.id} as checklist
    for source in template.TemplateStep limit=100
     create Step {parent=checklist,title=source.title,due=add_days(employee.start,source.offset_days),assignee=employee.user,category=source.category} as step
  # Record completion by the assigned employee or HR independently of document upload. @{nl="Registreer afronding door de toegewezen medewerker of HR onafhankelijk van documentupload."}
  export scenario complete(step:Step) by=hr or authenticated
   require step.parent.parent.active and (hr or step.assignee==actor) and not step.done and step.blocked_reason==null
   do set step {done=true,completed_by=actor,completed_at=now}
   examples step=test_step
    as,step.assignee,step.blocked_reason -> step.done
    members,self,null -> true
    members,other,null -> error(rule_failed)
    members,self,"Equipment missing" -> error(rule_failed)
  # Reopen a completed step with an attributed reason. @{nl="Heropen een afgeronde stap met een herleidbare reden."}
  scenario reopen(step:Step,reason:text) by=hr
   require step.done and trim(reason)!=""
   do set step {done=false,completed_by=null,completed_at=null,blocked_reason=reason}
  # Return only current eligible work under the canonical completion authority. @{nl="Geef alleen actueel uitvoerbaar werk terug binnen de canonieke afrondingsbevoegdheid."}
  export scenario work(locations:text[]) read=true scope=authority -> WorkBatch by=hr or authenticated
   do return WorkBatch {items=Step as item where (item.parent.parent.active and (hr or item.assignee==actor) and not item.done and item.blocked_reason==null) and (count(locations)==0 or item.parent.parent.home.id in locations) select WorkItem {reference=item.id,revision=item.version,location=item.parent.parent.home.id,title=item.title,detail=null,due=local_instant(item.due,"00:00",team.timezone,fold=earlier),action=action(complete,{step=item})}}
  # Revalidate the selected item before presenting its protected canonical action. @{nl="Controleer het gekozen item opnieuw voordat de beschermde canonieke actie wordt getoond."}
  export scenario work_detail(record:Step) read=true scope=authority -> WorkItem by=hr or authenticated
   require record.parent.parent.active and (hr or record.assignee==actor) and not record.done and record.blocked_reason==null
   do return WorkItem {reference=record.id,revision=record.version,location=record.parent.parent.home.id,title=record.title,detail=null,due=local_instant(record.due,"00:00",team.timezone,fold=earlier),action=action(complete,{step=record})}
 Then
  # Follow your assigned readiness work and private attachments. @{nl="Volg je toegewezen inwerkstappen en private bijlagen."}
  page /people/my-readiness title="My readiness"@{nl="Mijn inwerkstappen"}
   require authenticated
   card "Assigned readiness steps"@{nl="Toegewezen inwerkstappen"}
    tabs preferences.view
    list Step as step where step.assignee==actor and (preferences.view==all or (preferences.view==unfinished and not step.done) or (preferences.view==overdue and not step.done and step.due<local_date(now,team.timezone))) order=step.due
     text row.title,row.due,row.blocked_reason,row.document
     action complete

  # Prepare work identities and role/location checklists under HR document grants. @{nl="Bereid werkidentiteiten en rol- en locatiechecklists voor binnen HR-documentrechten."}
  page /people/onboarding title=page_people_onboarding_title
   require hr
   card "Employee onboarding"@{nl="Medewerkers inwerken"}
    form Employee.create
   card "Dated checklist steps"@{nl="Gedateerde checkliststappen"}
    tabs preferences.view
    list Employee order=start filter=home,active,role search=role defaults={home=preferences.home} display=split
     edit
     form start
     action deactivate
     list row.Checklist
      metrics row.completed_steps,row.total_steps,row.progress
      form Step.create
      list row.Step as step where preferences.view==all or (preferences.view==unfinished and not step.done) or (preferences.view==overdue and not step.done and step.due<local_date(now,team.timezone)) order=due
       edit
       actions complete,reopen
       history
   card "Reusable templates"@{nl="Herbruikbare templates"}
    form Template.create
    list Template display=split
     text row.revision,row.active
     edit
     form TemplateStep.create
     list row.TemplateStep
      edit
      delete

# Own the canonical employee work identity; private HR fields remain separate from work grants. @{nl="Beheer de canonieke werkidentiteit van medewerkers; privépersoneelsvelden blijven gescheiden van werkbevoegdheden."}
package employee label="Employees"@{nl="Medewerkers"}
 use rent_catalog {Location,test_site}
 Given
  export role hr label="Human resources"@{nl="Personeelszaken"}
  export Employee { user:user unique, home:Location label="Home location"@{nl="Standplaats"}, locations:Location[] label="Locations"@{nl="Locaties"}, operator_wide:bool=false label="All operator locations"@{nl="Alle locaties van de exploitant"}, active:bool=true, start:date label="Employment start"@{nl="Start dienstverband"}, end:date? label="Employment end"@{nl="Einde dienstverband"}, manager:user? label="Line manager"@{nl="Leidinggevende"}, role:text label="Work role"@{nl="Werkrol"}, skills:text[] label="Skills"@{nl="Vaardigheden"}, private_notes:text? label="Private HR notes"@{nl="Privénotities personeelszaken"}, document:file? label="HR document"@{nl="Personeelsdocument"} } label="Employee"@{nl="Medewerker"}
  event EmployeeChanged { employee:Employee, active:bool, revision:int }
  export derive staff(person:user):bool = any(Employee as e,e.user==person and e.active and active_member(person,team))
  export derive can_work(person:user,location:Location):bool = any(Employee as e,e.user==person and e.active and active_member(person,team) and (e.operator_wide or e.home==location or location in e.locations))
  policy Employee read=hr
  policy Employee read=members and staff(actor) fields=user,home,locations,operator_wide,active,role,skills
  policy Employee read=authenticated where=row.user==actor
  require Employee: row.end==null or row.end>=row.start
  export fixture test_worker=Employee {user=self,home=test_site,locations=[test_site],start=date("2026-10-01"),role="operator"}
 When
  crud Employee by=hr fields=home,locations,operator_wide,start,end,manager,role,skills,private_notes,document create_fields=user,home,locations,start,manager,role,skills delete=none
  # Deny new work immediately; downstream scheduling reconciliation remains separate. @{nl="Weiger nieuw werk onmiddellijk; reconciliatie van afhankelijke planning blijft afzonderlijk."}
  export scenario deactivate(employee:Employee,ended:date label="Employment end date"@{nl="Einddatum dienstverband"}) by=hr label="End active employment"@{nl="Actief dienstverband beëindigen"}
   require employee.active and ended>=employee.start
   do
    set employee {active=false,end=ended}
    emit EmployeeChanged {employee,active=false,revision=employee.version+1}
 Then

  message label_Swap_substitute = "Proposed substitute"@{nl="Voorgestelde vervanger"}
  export contract CommitmentRequest { source:text label=label_CommitmentRequest_source, employee:user label=label_CommitmentRequest_employee, location:text, from:datetime label=label_CommitmentRequest_from, until:datetime label=label_CommitmentRequest_until, before:duration=0m label=label_CommitmentRequest_before, after:duration=0m label=label_CommitmentRequest_after, skill:text label=label_CommitmentRequest_skill, kind:enum(duty,visit,appointment,absence,interview) label={text=label_CommitmentRequest_kind,values={duty=label_CommitmentRequest_kind_duty,visit=label_CommitmentRequest_kind_visit,appointment=label_CommitmentRequest_kind_appointment,absence=label_CommitmentRequest_kind_absence,interview=label_CommitmentRequest_kind_interview}}, revision:int } label="Employee commitment request"@{nl="Aanvraag personeelsinzet"}
  export capability ScheduleV1 version=1
   reserve(value:CommitmentRequest) -> OperationOutcome
   stage(value:CommitmentRequest,previous_source:text,previous_revision:int) -> OperationOutcome
   release(source:text,revision:int) -> OperationOutcome
